"""Freeze the explicit reviewed choices; build.py consumes selection.json offline."""
from pathlib import Path
import json
P=Path(__file__).resolve().parent
rows=[]
def cell(city,name,variant,note):rows.append({'municipality':city,'name':name,'candidateId':city+':'+name+':'+variant,'approximationNote':note})
def source(city,name,ident,note,component=None):
 r={'municipality':city,'name':name,'sourceAreaId':ident,'approximationNote':note}
 if component is not None:r['sourceComponent']=component
 rows.append(r)
def trace(city,name,coords,roads,note,urls=[]):rows.append({'municipality':city,'name':name,'coordinates':coords+[coords[0]],'roadNames':roads,'supportingUrls':urls,'approximationNote':note})
city='Hosszúpályi'
for name,var,note in [
('Dezső rész','rural','Actual forest tracks and watercourses close a broad rural map cell of about 0.706km² at this historical forest locality. The cell is a rough locality search area; the name association is inferred and not an official district border.'),
('Farkasgaz','rural','Actual rural track/watercourse cell around the Farkasgaz label and the independently named Farkasgaz tanya source farm. Includes the farm surroundings rather than only buildings; association with the whole cell is estimated.'),
('Homoktelep','rural','Actual local roads, tracks and drainage lines delimit the eastern settlement-edge cell at Homoktelep. A rough whole-locality search area including residential and adjoining garden land; not an official quarter boundary.'),
('Molnárkút','street','Actual street/watercourse cell around Molnárkút utca on the western settlement edge. Estimated local area; the point labels the map cell rather than creating its outline.'),
('Vénkert','rural','Actual garden access roads and drainage lines enclose this Vénkert garden-area cell north of the village. A low-confidence local search area, potentially only part of the wider historical garden name.')]:cell(city,name,var,note)
source(city,'Hosszúgaz','osm:way:1026072197','Unchanged whole source polygon explicitly named Hosszúgaz tanya. Associated with the nearby Hosszúgaz locality label; this is the farmstead parcel itself and is not a claim to all surrounding historical fields. It is a source map polygon, not a building union or radius.')
source(city,'Szalmás','osm:way:521950385','Unchanged whole source polygon explicitly named Szalmás tanya, at the end of its named access road. Associated with the nearby Szalmás locality label. The mapped farmstead area is retained; wider agricultural extent is not established.')
trace(city,'Szőlőskertek',[[21.7350,47.4032],[21.7391,47.4129],[21.7418,47.4157],[21.7519,47.4166],[21.7530,47.4119],[21.7504,47.4075],[21.7512,47.4024],[21.7450,47.4008],[21.7387,47.4020]],['Vénkert dűlő','Kolduskert dűlő','Vénkert utca','Tence csatorna'],'Rough manual outline of the contiguous garden/access-road fabric north of Hosszúpályi, guided by actual garden tracks, field/forest transitions and the Tence channel. Includes the wider Szőlőskertek area and can overlap the smaller Vénkert locality. Outer northern/eastern garden transitions are estimated, not a printed named-quarter border.')
city='Monostorpályi'
for name,var,note in [
('Csonkás','rural','Actual rural tracks and drainage enclose this cell at Csonkás, beside the separately named Csonkás tanya source farm. It includes the farm setting and surrounding plots, not only farm buildings; name-to-cell association is approximate.'),
('Gugyori','rural','Broad actual track/road/watercourse cell west of Monostorpályi around the Gugyori label, including the rural settlement setting and adjoining fields. It is an estimated locality area, not an official administrative quarter.'),
('Magyarkert','major','Actual main/local road courses enclose the western Magyarkert village-edge area. The choice preserves a larger coherent local area rather than the small street block at the name point. Internal and village-level subdivisions may overlap.'),
('Tejfeles','rural','Actual rural track and drainage network closes this garden/field area north of the village at Tejfeles. Historical local literature describes vineyard cultivation in Tejfeles; the cell association is a rough inference, not the historical cadastral perimeter.')]:cell(city,name,var,note)
source(city,'Liliom','osm:way:1030855479','Unchanged whole source farmstead parcel explicitly named Liliom tanya and containing the Liliom locality point. Preserves the entire mapped farm site; association of the short locality name is estimated and surrounding agricultural fields are not declared part of the source parcel.')
city='Orosháza'
for name,var,note in [
('Dr. László Elek-lakótelep','street','Actual local street courses enclose the coherent estate area at its name point, including the internal Dr. László Elek lakótelep service streets. The municipal TAK independently lists the estate. This is a physical street-area estimate, not an official estate border.'),
('Hajnal utcai lakótelep','street','Actual local street cell around the Hajnal estate blocks. The municipal TAK explicitly identifies the Hajnal street area as an estate. A rough estate-core search area; not a claimed cadastral border.'),
('Tass utcai lakótelep','street','Actual street cell around Tass street estate blocks. The municipal TAK independently lists the Tass street estate. A rough estate-core area, not a surveyed complete estate perimeter.'),
('Üveggyári lakótelep','street','Actual local street courses enclose the estate strip beside the glassworks at its preserved name point. The municipal TAK lists the estate and municipal planning material distinguishes the former factory service housing. Estimated association; does not rename the factory parcel as housing.')]:cell(city,name,var,note)
source(city,'Üveggyár','osm:relation:3062948','Unchanged actual industrial source polygon explicitly named Orosházi üveggyár. Associated with the Üveggyár locality point contained within it; the factory site itself is the mapped search area, distinct from the adjacent housing estate.')
